import{_ as i,C as o,o as a,c as n,a8 as r,E as l}from"./chunks/framework.C_Wqibly.js";const b=JSON.parse('{"title":"🏛️ Analisi del Marchio: Bticino (Legrand)","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/overview/brand/bticino.md","filePath":"blogs/overview/brand/bticino.md"}'),s={name:"blogs/overview/brand/bticino.md"};function d(c,t,g,m,p,u){const e=o("URL");return a(),n("div",null,[t[0]||(t[0]=r('<h1 id="🏛️-analisi-del-marchio-bticino-legrand" tabindex="-1">🏛️ Analisi del Marchio: Bticino (Legrand) <a class="header-anchor" href="#🏛️-analisi-del-marchio-bticino-legrand" aria-label="Permalink to &quot;🏛️ Analisi del Marchio: Bticino (Legrand)&quot;">​</a></h1><p><strong>Fascia di Prezzo:</strong> 🔴 Molto Alto (Premium)<br><strong>Valutazione Integrazione:</strong> ⭐ (1/5) - <em>Sistema chiuso, richiede workaround per il locale.</em></p><p>Bticino rappresenta l&#39;eccellenza dell&#39;<strong>integrazione architettonica</strong>. Nel tuo Sistema Ibrido, Bticino non è la scelta per il risparmio, ma per l&#39;estetica superiore (serie <strong>Living Now</strong>) e l&#39;affidabilità dei componenti fisici.</p><hr><h2 id="🔌-le-due-anime-di-bticino" tabindex="-1">🔌 Le Due Anime di Bticino <a class="header-anchor" href="#🔌-le-due-anime-di-bticino" aria-label="Permalink to &quot;🔌 Le Due Anime di Bticino&quot;">​</a></h2><h3 id="_1-myhome-cablato-scs" tabindex="-1">1. MyHome (Cablato SCS) <a class="header-anchor" href="#_1-myhome-cablato-scs" aria-label="Permalink to &quot;1. MyHome (Cablato SCS)&quot;">​</a></h3><p>Il sistema domotico professionale installato dagli elettricisti.</p><ul><li><strong>Integrazione HA:</strong> Richiede il gateway <strong>MyHomeServer1</strong>. Home Assistant comunica tramite protocollo <em>OpenWebNet</em>.</li><li><strong>Giudizio:</strong> Estremamente affidabile, ma molto costoso e rigido.</li></ul><h3 id="_2-living-now-con-netatmo-wireless-ibrido" tabindex="-1">2. Living Now con Netatmo (Wireless/Ibrido) <a class="header-anchor" href="#_2-living-now-con-netatmo-wireless-ibrido" aria-label="Permalink to &quot;2. Living Now con Netatmo (Wireless/Ibrido)&quot;">​</a></h3><p>La linea più interessante per noi. Utilizza il protocollo <strong>Zigbee</strong> (variante proprietaria Netatmo).</p><ul><li><strong>Vantaggi:</strong> Design incredibile, si installa nelle normali scatole 503, cover intercambiabili.</li><li><strong>Svantaggi:</strong> Richiede obbligatoriamente il suo Gateway Wi-Fi e l&#39;app <em>Home + Control</em>.</li></ul><hr><h2 id="🛠️-strategia-di-integrazione-il-ponte-locale" tabindex="-1">🛠️ Strategia di Integrazione: Il &quot;Ponte Locale&quot; <a class="header-anchor" href="#🛠️-strategia-di-integrazione-il-ponte-locale" aria-label="Permalink to &quot;🛠️ Strategia di Integrazione: Il &quot;Ponte Locale&quot;&quot;">​</a></h2><p>Per evitare di dipendere dal Cloud Legrand/Netatmo, la strategia migliore per Home Assistant è sfruttare <strong>HomeKit</strong> come protocollo di comunicazione locale.</p><h3 id="metodo-consigliato-homekit-controller" tabindex="-1">Metodo Consigliato: HomeKit Controller <a class="header-anchor" href="#metodo-consigliato-homekit-controller" aria-label="Permalink to &quot;Metodo Consigliato: HomeKit Controller&quot;">​</a></h3><ol><li><strong>Configurazione:</strong> Collega i dispositivi Bticino all&#39;app ufficiale e abilita Apple HomeKit.</li><li><strong>Integrazione HA:</strong> Usa l&#39;integrazione <strong>HomeKit Controller</strong> in Home Assistant.</li><li><strong>Risultato:</strong> HA &quot;vede&quot; il gateway Bticino sulla rete locale. I comandi sono istantanei e passano dal Wi-Fi di casa, <strong>non dal cloud</strong>.</li></ol><blockquote><p>💡 <strong>Vantaggio Ibrido:</strong> Puoi usare un lussuoso interruttore Bticino per attivare una lampadina economica Zigbee (es. Lidl o Ikea) grazie alla regia di Home Assistant.</p></blockquote><hr><h2 id="📐-anatomia-di-un-punto-luce-living-now" tabindex="-1">📐 Anatomia di un Punto Luce (Living Now) <a class="header-anchor" href="#📐-anatomia-di-un-punto-luce-living-now" aria-label="Permalink to &quot;📐 Anatomia di un Punto Luce (Living Now)&quot;">​</a></h2><p>Per comporre un punto luce completo servono sempre 4 elementi:</p><ol><li><strong>Supporto (K4703):</strong> Il telaio che si avvita alla scatola 503.</li><li><strong>Frutto (Dispositivo):</strong> L&#39;interruttore o la presa vera e propria.</li><li><strong>Cover:</strong> Il tasto estetico (Bianco, Sabbia o Nero).</li><li><strong>Placca:</strong> La cornice finale di finitura.</li></ol><h3 id="💶-listino-prezzi-stimati-singoli-componenti" tabindex="-1">💶 Listino Prezzi Stimati (Singoli Componenti) <a class="header-anchor" href="#💶-listino-prezzi-stimati-singoli-componenti" aria-label="Permalink to &quot;💶 Listino Prezzi Stimati (Singoli Componenti)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Componente</th><th style="text-align:left;">Codice</th><th style="text-align:left;">Descrizione</th><th style="text-align:left;">Prezzo Medio</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Supporto</strong></td><td style="text-align:left;">K4703</td><td style="text-align:left;">Supporto 3 moduli con viti</td><td style="text-align:left;">€ 2,50 - 3,00</td></tr><tr><td style="text-align:left;"><strong>Placca Bianca</strong></td><td style="text-align:left;">KA4803KW</td><td style="text-align:left;">Placca Living Now 3 mod.</td><td style="text-align:left;">€ 7,00</td></tr><tr><td style="text-align:left;"><strong>Interruttore std</strong></td><td style="text-align:left;">K4001</td><td style="text-align:left;">Unipolare 10AX</td><td style="text-align:left;">€ 4,50</td></tr><tr><td style="text-align:left;"><strong>Presa Bipasso</strong></td><td style="text-align:left;">K4141</td><td style="text-align:left;">Presa 10/16A (Standard ITA)</td><td style="text-align:left;">€ 6,00</td></tr><tr><td style="text-align:left;"><strong>Cover Tasto</strong></td><td style="text-align:left;">KW01</td><td style="text-align:left;">Cover per interruttore 1 mod.</td><td style="text-align:left;">€ 1,50 - 2,00</td></tr><tr><td style="text-align:left;"><strong>Comando Smart</strong></td><td style="text-align:left;">K4500C</td><td style="text-align:left;">Interruttore connesso Zigbee</td><td style="text-align:left;">€ 45,00 - 50,00</td></tr></tbody></table><hr><h2 id="🛒-esempi-di-composizioni-complete" tabindex="-1">🛒 Esempi di Composizioni Complete <a class="header-anchor" href="#🛒-esempi-di-composizioni-complete" aria-label="Permalink to &quot;🛒 Esempi di Composizioni Complete&quot;">​</a></h2><p>Ecco quanto costa mediamente un punto luce completo (Serie Living Now Bianca):</p><h3 id="_1-punto-luce-3-tasti-standard-non-smart" tabindex="-1">1. Punto Luce 3 Tasti Standard (Non Smart) <a class="header-anchor" href="#_1-punto-luce-3-tasti-standard-non-smart" aria-label="Permalink to &quot;1. Punto Luce 3 Tasti Standard (Non Smart)&quot;">​</a></h3><p><em>Ideale per zone dove non serve automazione ma solo estetica.</em></p><ul><li>1 Supporto + 1 Placca Bianca + 3 Deviatori + 3 Cover.</li><li><strong>TOTALE: € 32,00</strong></li></ul><h3 id="_2-combo-2-tasti-1-presa-bipasso" tabindex="-1">2. Combo 2 Tasti + 1 Presa Bipasso <a class="header-anchor" href="#_2-combo-2-tasti-1-presa-bipasso" aria-label="Permalink to &quot;2. Combo 2 Tasti + 1 Presa Bipasso&quot;">​</a></h3><p><em>La classica combinazione da comodino.</em></p><ul><li>1 Supporto + 1 Placca Bianca + 2 Deviatori + 2 Cover + 1 Presa + 1 Cover Presa.</li><li><strong>TOTALE: € 32,00</strong></li></ul><h3 id="_3-presa-schuko-1-tasto" tabindex="-1">3. Presa Schuko + 1 Tasto <a class="header-anchor" href="#_3-presa-schuko-1-tasto" aria-label="Permalink to &quot;3. Presa Schuko + 1 Tasto&quot;">​</a></h3><p><em>Per cucina o elettrodomestici pesanti.</em></p><ul><li>1 Supporto + 1 Placca Bianca + 1 Presa Schuko (2 mod) + 1 Cover Schuko + 1 Deviatore con Cover.</li><li><strong>TOTALE: € 29,00</strong></li></ul><hr><h2 id="💡-nota-strategica-per-il-risparmio" tabindex="-1">💡 Nota Strategica per il Risparmio <a class="header-anchor" href="#💡-nota-strategica-per-il-risparmio" aria-label="Permalink to &quot;💡 Nota Strategica per il Risparmio&quot;">​</a></h2><p>Rendere &quot;Smart&quot; ogni singolo tasto Bticino costa circa <strong>€50 a punto luce</strong>.</p><p><strong>Il consiglio dell&#39;esperto:</strong> Usa i frutti standard Bticino (economici) e inserisci dietro di essi un <strong>modulo Shelly (Wi-Fi)</strong> o un <strong>modulo Zigbee (Sonoff/Aqara)</strong>. Otterrai lo stesso risultato smart, manterrai l&#39;estetica Living Now, ma pagherai l&#39;intelligenza solo <strong>€15-20</strong> invece di €50.</p>',39)),l(e,{id:"c6XXwhSu0uM?si=PimscilPHGut-ZNz"})])}const f=i(s,[["render",d]]);export{b as __pageData,f as default};
